namespace fs=std::filesystem;using namespace csc_descriptor;
static std::string env(const char*n){const char*v=std::getenv(n);return v?v:"";}
static std::string list(const std::vector<uint64_t>&v){std::ostringstream o;for(size_t i=0;i<v.size();++i){if(i)o<<';';o<<v[i];}return o.str();}
TEST(CSCDescriptorBenchmark, ExplicitRun){std::string path=env("CSC_DESCRIPTOR_MATRIX");if(env("CSC_DESCRIPTOR_BENCHMARK_RUN")!="1"||path.empty())GTEST_SKIP()<<"set CSC_DESCRIPTOR_BENCHMARK_RUN=1 and CSC_DESCRIPTOR_MATRIX";auto a=std::chrono::steady_clock::now();auto m=loadCSC(path);auto l=buildLayout(m,MappingPolicy::RoundRobin);double layout_ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-a).count();std::vector<float>x(m.cols);for(uint32_t i=0;i<m.cols;++i)x[i]=float((i%17)+1)/17;a=std::chrono::steady_clock::now();auto ref=cpuReference(m,x);double ref_ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-a).count();auto f=executeLockstep(l,x);float maxe;uint32_t first;ASSERT_TRUE(compareResults(ref,f.y,&maxe,&first))<<"max_error="<<maxe<<" first_row="<<first;CSCTimingModel tm;auto t=tm.run(l,f.stats);std::string run=env("CSC_DESCRIPTOR_RUN_ID");if(run.empty()){auto now=std::chrono::system_clock::now().time_since_epoch();run=std::to_string(std::chrono::duration_cast<std::chrono::seconds>(now).count());}fs::create_directories("results/csc");std::string name=fs::path(path).stem().string()+"_round_robin_fp32_64bg_"+run+".csv";fs::path outp=fs::path("results/csc")/name;ASSERT_FALSE(fs::exists(outp))<<"refusing overwrite";std::ofstream o(outp);o<<"matrix,rows,cols,nnz,mapping,precision,global_bg,descriptors,useful_value_bytes,value_padding_bytes,physical_value_bytes,useful_index_bytes,index_padding_bytes,physical_index_bytes,total_padding_bytes,alignment_overhead_ratio,x_useful_bytes,x_padding_bytes,descriptor_bytes,max_bg_nnz,avg_bg_nnz,load_cv,bg_nnz,bg_descriptor_count,total_chunks,full_chunks,tail_chunks,active_lanes,available_lanes,lane_utilization,lockstep_rounds,critical_bg,bg_chunk_count,bg_idle_round_count,x_scalar_loads,x_burst_reads,value_burst_reads,index_burst_reads,logical_mul_events,partials,host_accumulations,matrix_preload_bursts,result_bursts,matrix_preload_cycles,x_load_cycles,value_read_cycles,index_read_cycles,result_cycles,synchronization_drain_cycles,kernel_resident_cycles,kernel_with_x_cycles,end_to_end_cycles,cpu_reference_ms,layout_ms,x_packing_ms,multiply_ms,host_accumulation_ms,max_error,validation_passed\n";auto&s=l.stats;auto&e=f.stats;o<<fs::path(path).stem().string()<<','<<m.rows<<','<<m.cols<<','<<m.values.size()<<",round_robin,FP32,64,"<<s.descriptor_count<<','<<s.useful_value_bytes<<','<<s.value_alignment_padding_bytes<<','<<s.physical_value_bytes<<','<<s.useful_index_bytes<<','<<s.index_alignment_padding_bytes<<','<<s.physical_index_bytes<<','<<s.total_alignment_padding_bytes<<','<<s.alignment_overhead_ratio<<','<<s.x_useful_bytes<<','<<s.x_padding_bytes<<','<<s.descriptor_bytes<<','<<s.max_bg_nnz<<','<<s.average_bg_nnz<<','<<s.load_cv<<",\""<<list(s.bg_nnz)<<"\",\""<<list(s.bg_descriptor_count)<<"\","<<e.total_chunks<<','<<e.full_chunks<<','<<e.tail_chunks<<','<<e.active_lanes<<','<<e.total_available_lanes<<','<<e.simd_lane_utilization<<','<<e.total_lockstep_rounds<<','<<e.critical_bg<<",\""<<list(e.bg_chunk_count)<<"\",\""<<list(e.bg_idle_round_count)<<"\","<<e.x_scalar_load_count<<','<<t.x_bursts<<','<<t.value_bursts<<','<<t.row_index_bursts<<','<<e.logical_csc_mul_events<<','<<e.generated_partial_count<<','<<e.host_accumulation_count<<','<<t.matrix_preload_bursts<<','<<t.result_bursts<<','<<t.matrix_preload_cycles<<','<<t.x_load_cycles<<','<<t.value_read_cycles<<','<<t.row_index_read_cycles<<','<<t.result_cycles<<','<<t.synchronization_drain_cycles<<','<<t.kernel_resident_cycles<<','<<t.kernel_with_x_cycles<<','<<t.end_to_end_simulated_cycles<<','<<ref_ms<<','<<layout_ms<<','<<e.x_packing_wall_ms<<','<<e.multiplication_wall_ms<<','<<e.host_accumulation_wall_ms<<','<<maxe<<",1\n";std::cout<<"CSC_DESCRIPTOR_RESULT="<<outp<<std::endl;}
